import{_ as l,o as e,c as o,a2 as i}from"./chunks/framework.BXzK3EA4.js";const c=JSON.parse('{"title":"裸机云控制台操作指南","description":"","frontmatter":{"title":"裸机云控制台操作指南"},"headers":[],"relativePath":"ops-knowledge-base/baremetal/console-guide.md","filePath":"ops-knowledge-base/baremetal/console-guide.md","lastUpdated":1794309341000}'),r={name:"ops-knowledge-base/baremetal/console-guide.md"};function t(h,a,p,n,u,s){return e(),o("div",null,[...a[0]||(a[0]=[i('<h2 id="用途" tabindex="-1">用途 <a class="header-anchor" href="#用途" aria-label="Permalink to &quot;用途&quot;">​</a></h2><p>本文档主要介绍裸机云控制台各功能模块及基本操作，帮助客户快速熟悉后台管理页面。</p><p>对于升级/降级、快照、安全组等功能，本文仅作简单介绍，详细操作请参考对应的知识库文档。</p><p><strong>适用产品：</strong> 裸机云（Bare Metal Cloud）</p><hr><h2 id="一、进入裸机云控制台" tabindex="-1">一、进入裸机云控制台 <a class="header-anchor" href="#一、进入裸机云控制台" aria-label="Permalink to &quot;一、进入裸机云控制台&quot;">​</a></h2><ol><li>登录 Raksmart 客户后台。</li><li>在左侧菜单栏选择 <strong>产品管理</strong> → <strong>裸机云</strong>。</li><li>找到需要管理的裸机云产品。</li><li>点击产品名称进入服务器管理页面。</li></ol><p>进入后，页面顶部可看到以下功能模块：</p><ul><li>管理</li><li>配置选项</li><li>监控</li><li>附加功能</li><li>应用</li><li>快照</li></ul><hr><h2 id="二、管理" tabindex="-1">二、管理 <a class="header-anchor" href="#二、管理" aria-label="Permalink to &quot;二、管理&quot;">​</a></h2><p>&quot;管理&quot;页面提供服务器最常用的管理功能，可用于服务器电源控制、系统维护及远程管理。</p><h2 id="状态刷新" tabindex="-1">状态刷新 <a class="header-anchor" href="#状态刷新" aria-label="Permalink to &quot;状态刷新&quot;">​</a></h2><p>点击 <strong>状态刷新</strong> 可更新服务器当前运行状态。</p><p>适用于：</p><ul><li>查看服务器是否已开机</li><li>查看关机、重启等操作是否已完成</li></ul><hr><h2 id="开机" tabindex="-1">开机 <a class="header-anchor" href="#开机" aria-label="Permalink to &quot;开机&quot;">​</a></h2><p>当服务器处于关机状态时，可点击 <strong>开机</strong> 启动服务器。</p><p>适用于：</p><ul><li>服务器已关机</li><li>停机维护完成后恢复运行</li></ul><hr><h2 id="关机" tabindex="-1">关机 <a class="header-anchor" href="#关机" aria-label="Permalink to &quot;关机&quot;">​</a></h2><p>点击 <strong>关机</strong> 可正常关闭服务器操作系统。</p><p>建议在进行硬件维护、系统调整或长时间停机前使用。</p><blockquote><p><strong>注意：</strong> 建议先停止业务或确认无重要任务正在运行，以免影响业务正常使用。</p></blockquote><hr><h2 id="重启" tabindex="-1">重启 <a class="header-anchor" href="#重启" aria-label="Permalink to &quot;重启&quot;">​</a></h2><p>点击 <strong>重启</strong> 可正常重新启动服务器。</p><p>适用于：</p><ul><li>修改系统配置后使配置生效</li><li>系统更新完成后重启</li><li>系统运行异常需要重新启动</li></ul><hr><h2 id="硬关机" tabindex="-1">硬关机 <a class="header-anchor" href="#硬关机" aria-label="Permalink to &quot;硬关机&quot;">​</a></h2><p>点击 <strong>硬关机</strong> 可直接关闭服务器电源。</p><blockquote><p><strong>注意：</strong></p><p>硬关机不会通知操作系统正常退出，可能导致数据丢失或文件系统损坏，仅建议在服务器无法正常关机时使用。</p></blockquote><hr><h2 id="vnc-控制台" tabindex="-1">VNC 控制台 <a class="header-anchor" href="#vnc-控制台" aria-label="Permalink to &quot;VNC 控制台&quot;">​</a></h2><p>VNC 可直接连接服务器控制台，即使服务器网络异常或 SSH/RDP 无法连接，也可以进行操作。</p><p>常见使用场景：</p><ul><li>SSH 无法连接</li><li>RDP 无法连接</li><li>系统启动异常</li><li>修改系统密码</li><li>进入单用户模式</li><li>查看系统启动过程</li></ul><blockquote><p>详细操作请参考：《<a href="/ops-knowledge-base/baremetal/vnc-console-guide.html">裸机云 VNC 控制台使用指南</a>》</p></blockquote><hr><h2 id="重置密码" tabindex="-1">重置密码 <a class="header-anchor" href="#重置密码" aria-label="Permalink to &quot;重置密码&quot;">​</a></h2><p>可用于重新设置服务器系统登录密码。</p><p>适用于：</p><ul><li>忘记系统登录密码</li><li>首次修改系统密码</li></ul><blockquote><p>详细操作请参考：《<a href="/ops-knowledge-base/baremetal/password-change-reset-guide.html">裸机云密码修改与重置指南</a>》</p></blockquote><hr><h2 id="重装系统" tabindex="-1">重装系统 <a class="header-anchor" href="#重装系统" aria-label="Permalink to &quot;重装系统&quot;">​</a></h2><p>用于重新安装服务器操作系统。</p><p>支持安装 Linux、Windows 等系统（具体以后台可选系统为准）。</p><blockquote><p><strong>注意：</strong></p><p>重装系统会清空系统盘中的所有数据，请提前做好重要数据备份。</p></blockquote><blockquote><p>详细操作请参考：《<a href="/ops-knowledge-base/baremetal/reinstall-os-guide.html">裸机云重装系统指南</a>》</p></blockquote><hr><h2 id="救援系统-rescue" tabindex="-1">救援系统（Rescue） <a class="header-anchor" href="#救援系统-rescue" aria-label="Permalink to &quot;救援系统（Rescue）&quot;">​</a></h2><p>当服务器系统无法正常启动时，可进入 Rescue 模式进行系统修复或数据恢复。</p><p>常见使用场景：</p><ul><li>系统无法启动</li><li>文件系统修复</li><li>修复启动配置</li><li>数据恢复</li></ul><blockquote><p>详细操作请参考：《<a href="/ops-knowledge-base/baremetal/rescue-mode-guide.html">裸机云救援系统（Rescue）使用指南</a>》</p></blockquote><hr><h2 id="升级-降级" tabindex="-1">升级/降级 <a class="header-anchor" href="#升级-降级" aria-label="Permalink to &quot;升级/降级&quot;">​</a></h2><p>可根据业务需求调整服务器资源配置。</p><p>支持调整的项目以后台显示为准，例如：</p><ul><li>CPU</li><li>内存</li><li>带宽</li><li>流量</li></ul><blockquote><p>详细操作请参考：《<a href="/ops-knowledge-base/baremetal/upgrade-downgrade-guide.html">裸机云升级/降级操作指南</a>》</p></blockquote><hr><h2 id="三、配置选项" tabindex="-1">三、配置选项 <a class="header-anchor" href="#三、配置选项" aria-label="Permalink to &quot;三、配置选项&quot;">​</a></h2><p>&quot;配置选项&quot;页面用于查看当前服务器的资源配置。</p><p>可查看的信息包括：</p><ul><li>CPU 配置</li><li>内存大小</li><li>系统盘规格</li><li>带宽类型</li><li>带宽大小</li><li>流量规格</li><li>高防 IP（如已购买）</li></ul><p>如需确认服务器配置或线路信息，可在此页面查看。</p><blockquote><p><strong>说明：</strong></p><p>此页面仅用于查看配置信息，不支持直接修改配置。</p></blockquote><hr><h2 id="四、监控" tabindex="-1">四、监控 <a class="header-anchor" href="#四、监控" aria-label="Permalink to &quot;四、监控&quot;">​</a></h2><p>&quot;监控&quot;页面用于查看服务器资源使用情况，帮助客户了解服务器运行状态。</p><p>目前支持查看以下监控数据：</p><ul><li>CPU 使用率</li><li>硬盘 IO</li><li>内存使用率</li><li>网卡流量</li><li>流量统计</li></ul><p>客户可根据监控图表分析服务器资源使用情况，例如：</p><ul><li>CPU 是否持续占用过高</li><li>是否存在异常磁盘读写</li><li>内存是否不足</li><li>网络流量是否异常</li></ul><blockquote><p>详细操作请参考：《<a href="/ops-knowledge-base/baremetal/monitoring-guide.html">裸机云监控功能说明</a>》</p></blockquote><hr><h2 id="五、附加功能" tabindex="-1">五、附加功能 <a class="header-anchor" href="#五、附加功能" aria-label="Permalink to &quot;五、附加功能&quot;">​</a></h2><p>&quot;附加功能&quot;页面主要用于管理服务器的网络相关功能。</p><p>目前支持：</p><ul><li>创建安全组</li><li>管理安全组</li><li>删除安全组</li><li>将安全组应用到服务器</li><li>取消安全组应用</li></ul><p>安全组可用于控制服务器允许访问的端口及网络策略，提高服务器安全性。</p><blockquote><p>详细操作请参考：《<a href="/ops-knowledge-base/vps/security-group-guide.html">裸机云安全组使用指南</a>》</p></blockquote><hr><h2 id="六、应用" tabindex="-1">六、应用 <a class="header-anchor" href="#六、应用" aria-label="Permalink to &quot;六、应用&quot;">​</a></h2><p>&quot;应用&quot;页面用于管理系统应用或扩展功能。</p><p>根据产品及系统不同，可提供相应的应用管理功能。</p><p>如页面无可用应用，则无需进行任何操作。</p><hr><h2 id="七、快照" tabindex="-1">七、快照 <a class="header-anchor" href="#七、快照" aria-label="Permalink to &quot;七、快照&quot;">​</a></h2><p>快照用于保存当前服务器状态，以便后续恢复。</p><p>建议在以下场景创建快照：</p><ul><li>系统升级前</li><li>安装软件前</li><li>修改重要配置前</li><li>业务上线前</li></ul><blockquote><p><strong>注意：</strong></p><p>快照主要用于快速恢复服务器状态，不能替代长期的数据备份。重要业务数据仍建议定期进行独立备份。</p></blockquote><blockquote><p>详细操作请参考：《裸机云快照使用指南》</p></blockquote><hr><h2 id="八、常见问题" tabindex="-1">八、常见问题 <a class="header-anchor" href="#八、常见问题" aria-label="Permalink to &quot;八、常见问题&quot;">​</a></h2><h3 id="_1-为什么点击关机后服务器没有立即关闭" tabindex="-1">1. 为什么点击关机后服务器没有立即关闭？ <a class="header-anchor" href="#_1-为什么点击关机后服务器没有立即关闭" aria-label="Permalink to &quot;1. 为什么点击关机后服务器没有立即关闭？&quot;">​</a></h3><p>服务器执行的是正常关机流程，具体耗时取决于操作系统及当前运行的服务，请耐心等待并刷新服务器状态。</p><hr><h3 id="_2-什么时候需要使用硬关机" tabindex="-1">2. 什么时候需要使用硬关机？ <a class="header-anchor" href="#_2-什么时候需要使用硬关机" aria-label="Permalink to &quot;2. 什么时候需要使用硬关机？&quot;">​</a></h3><p>仅建议在服务器无法正常响应、无法执行正常关机时使用。正常情况下，请优先使用&quot;关机&quot;功能。</p><hr><h3 id="_3-重装系统会删除服务器数据吗" tabindex="-1">3. 重装系统会删除服务器数据吗？ <a class="header-anchor" href="#_3-重装系统会删除服务器数据吗" aria-label="Permalink to &quot;3. 重装系统会删除服务器数据吗？&quot;">​</a></h3><p>会。重装系统会清空系统盘中的所有数据，请提前做好数据备份。</p><hr><h3 id="_4-vnc-与-ssh-或-windows-rdp-有什么区别" tabindex="-1">4. VNC 与 SSH（或 Windows RDP）有什么区别？ <a class="header-anchor" href="#_4-vnc-与-ssh-或-windows-rdp-有什么区别" aria-label="Permalink to &quot;4. VNC 与 SSH（或 Windows RDP）有什么区别？&quot;">​</a></h3><p>SSH 和 RDP 属于网络远程登录方式，而 VNC 为服务器控制台连接。即使服务器网络异常、SSH 或 RDP 无法连接，通常仍可通过 VNC 登录服务器进行管理。</p><hr><h3 id="_5-为什么配置页面不能直接修改-cpu、内存或带宽" tabindex="-1">5. 为什么配置页面不能直接修改 CPU、内存或带宽？ <a class="header-anchor" href="#_5-为什么配置页面不能直接修改-cpu、内存或带宽" aria-label="Permalink to &quot;5. 为什么配置页面不能直接修改 CPU、内存或带宽？&quot;">​</a></h3><p>配置选项页面仅用于查看当前服务器配置。如需调整资源配置，请使用&quot;升级/降级&quot;功能，具体操作请参考《裸机云升级/降级操作指南》。</p><hr>',116)])])}const b=l(r,[["render",t]]);export{c as __pageData,b as default};
